    if (
      startActiveSpanArgs.length === 2 &&
      typeof startActiveSpanArgs[1] === 'function'
    ) {
      fnIdx = 1
    } else if (
      startActiveSpanArgs.length === 3 &&
      typeof startActiveSpanArgs[2] === 'function'
    ) {
